def process(n, m):
    f_dict = {0: 0, 1: 1, 2: 2}
    for i in range(3, n+1):
        f_dict[i] = 2*f_dict[i-1]
        for x in factors(i):
            if 2 <= x <= i:
                f_dict[i] += f_dict[(i//x)]-f_dict[(i-1)//x]
                f_dict[i] = f_dict[i] % m
        f_dict[i] = f_dict[i] % m
    return f_dict[n]

