        for x in range(m-(i-1)*(i-2)//2, m+(i-1)*(i-2)//2+1):
            for d in range(1, i):
                dp1[i][x-d] = (dp1[i][x-d]+dp[i-1][x]*(i-d)) % mod

    return sum(dp1[-1][m+1:]) % mod

